alter table public.shops add column if not exists name text,add column if not exists description text,add column if not exists category text,add column if not exists address text,add column if not exists phone text,add column if not exists facebook text,add column if not exists line text,add column if not exists tiktok text,add column if not exists website text,add column if not exists image text,add column if not exists latitude double precision,add column if not exists longitude double precision,add column if not exists approved boolean not null default false,add column if not exists featured boolean not null default false,add column if not exists created_at timestamptz not null default now(),add column if not exists updated_at timestamptz not null default now();
alter table public.shops enable row level security;
drop policy if exists "Anyone can view approved shops" on public.shops;
create policy "Anyone can view approved shops" on public.shops for select to anon,authenticated using (approved=true);
drop policy if exists "Anyone can submit unapproved shops" on public.shops;
create policy "Anyone can submit unapproved shops" on public.shops for insert to anon,authenticated with check (approved=false and featured=false);
insert into public.shops(name,description,category,address,phone,facebook,line,latitude,longitude,approved,featured) select 'Snowtee ตลาดกระทุ่มแบน','เครื่องดื่ม ไอศกรีมซอฟต์เสิร์ฟ และเบเกอรี่ บรรยากาศริมคลอง','เครื่องดื่ม','ตลาดกระทุ่มแบน จังหวัดสมุทรสาคร','0642211876','https://facebook.com/snowtee68','snowtee68',13.6549,100.2639,true,true where not exists(select 1 from public.shops where name='Snowtee ตลาดกระทุ่มแบน');